def solve(g):
    h,w=len(g),len(g[0])
    cnt=defaultdict(int)
    for row in g:
        for v in row: cnt[v]+=1
    bg=max(cnt,key=lambda k:cnt[k])
    dots=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]!=bg]
    out=[row[:] for row in g]
    def paint(cells,col):
        for r,c in cells:
            if 0<=r<h and 0<=c<w and g[r][c]==bg:
                out[r][c]=col
    def seg(p,q):
        dr=(q[0]>p[0])-(q[0]<p[0]); dc=(q[1]>p[1])-(q[1]<p[1])
        r,c=p; res=[]
        while (r,c)!=(q[0]+dr,q[1]+dc) if (dr or dc) else False:
            res.append((r,c)); r+=dr; c+=dc
        return res
    def full_line(p,main):
        res=[]
        if main:
            for k in range(-max(h,w),max(h,w)+1):
                res.append((p[0]+k,p[1]+k))
        else:
            for k in range(-max(h,w),max(h,w)+1):
                res.append((p[0]+k,p[1]-k))
        return [(r,c) for r,c in res if 0<=r<h and 0<=c<w]
    def ondiag(p,q): return p[0]-q[0]==p[1]-q[1] or p[0]+p[1]==q[0]+q[1]
    bycol=defaultdict(list)
    for d in dots: bycol[d[2]].append((d[0],d[1]))
    colors=sorted(bycol)
    perp=set(colors[1:])  # every color except the smallest gets the full perpendicular
    for v in colors:
        pts=bycol[v]
        for p in pts:
            same=[q for q in pts if q!=p and ondiag(p,q)]
            if same:
                q=min(same,key=lambda q:abs(q[0]-p[0])+abs(q[1]-p[1]))
                paint(seg(p,q),v)
                if v in perp:
                    main = (p[0]-q[0]==p[1]-q[1])  # shared is main -> perp is anti
                    paint(full_line(p,not main),v)
            else:
                cross=[q for q in dots if q[2]!=v and ondiag((p[0],p[1]),(q[0],q[1]))]
                if cross:
                    q=min(((q[0],q[1]) for q in cross),key=lambda q:abs(q[0]-p[0])+abs(q[1]-p[1]))
                    if v in perp:
                        main = (p[0]-q[0]==p[1]-q[1])
                        paint(full_line(p,not main),v)
                    else:
                        t=(p[1],p[0])
                        if t[0]<h and t[1]<w: paint(seg(p,t),v)
    return out

